using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace QiDesk {
public static class ComponentFeatureTests {
    public static void Run(string root,Action<bool,string> check){
        var store=new Store(Path.Combine(root,"component-tests"));store.Data.Groups.Clear();check(new System.Collections.Generic.HashSet<string>(WidgetPlugins.Builtins().Select(p=>p.Kind)).SetEquals(WidgetPlugins.SupportedKinds),"component library includes fourteen usable widget renderers including desktop quick search");
        var track=NetEaseMusic.Split("夜曲 - 周杰伦");check(track.Length==2&&track[0]=="夜曲"&&track[1]=="周杰伦"&&NetEaseMusic.Split("纯音乐").Length==2&&NetEaseMusic.Split("纯音乐")[1]=="","NetEase Cloud Music now-playing parses title and artist from the client window title");check(WeatherService.Condition(0)=="晴朗"&&WeatherService.Condition(63)=="下雨"&&WeatherService.Condition(95)=="雷雨","weather card maps common forecast codes to readable Chinese conditions");
        check(Calc.Evaluate("2+3*4")=="14"&&Calc.Evaluate("(1+2)*3")=="9"&&Calc.Evaluate("10/4")=="2.5"&&Calc.Evaluate("6÷2")=="3"&&Calc.Evaluate("2+")==null&&Calc.Evaluate("1/0")==null,"calculator renderer evaluates arithmetic safely and rejects incomplete or undefined expressions");
        check(WidgetPlugins.HabitStreak(new[]{"2026-10-12","2026-10-13","2026-10-14"},new DateTime(2026,10,14))==3&&WidgetPlugins.HabitStreak(new[]{"2026-10-12","2026-10-13"},new DateTime(2026,10,14))==2&&WidgetPlugins.HabitStreak(new string[0],new DateTime(2026,10,14))==0,"habit renderer counts consecutive check-in days");
        int memoryPercent;double memoryUsed,memoryTotal;check(SystemMetrics.Memory(out memoryPercent,out memoryUsed,out memoryTotal)&&memoryPercent>=0&&memoryPercent<=100&&memoryTotal>0,"system renderer reads live memory metrics");
        double diskFree,diskTotal;string diskLabel;check(SystemMetrics.Disk("",out diskFree,out diskTotal,out diskLabel)&&diskTotal>0&&diskLabel.Length>0,"system renderer reads the system drive metrics");
        string photoFolder=Path.Combine(root,"photo-folder");Directory.CreateDirectory(photoFolder);File.WriteAllText(Path.Combine(photoFolder,"one.png"),"x");File.WriteAllText(Path.Combine(photoFolder,"two.jpg"),"x");File.WriteAllText(Path.Combine(photoFolder,"notes.txt"),"x");var photos=WidgetPlugins.Pictures(photoFolder,50);check(photos.Length==2&&photos.All(p=>Thumbnails.IsPicture(p))&&WidgetPlugins.Pictures(Path.Combine(root,"missing-folder"),50).Length==0,"photo renderer lists only pictures from an existing folder");
        var weatherJson=Store.Json.Deserialize<Dictionary<string,object>>("{\"results\":[{\"name\":\"北京\"}]}");check(weatherJson["results"] is System.Collections.ArrayList,"weather service parser accepts a geocoding results array");
        var custom=new WidgetPlugin(){Id="meal",Name="今天吃什么",Kind="choice",Text="面条\n米饭\n饺子",Description="随机选个午饭",Accent="#B8A1DA"};string pluginFile=Path.Combine(root,"meal.qidesk-plugin.json");File.WriteAllText(pluginFile,Store.Json.Serialize(PluginManifest.From(custom)));WidgetPlugins.Import(store.Data,WidgetPlugins.Read(pluginFile));
        var pack=ComponentPackages.FromPlugins(store.Data,new[]{"clock","calendar","qidesk.tasks","qidesk.focus","meal"},"我的专注桌面");check(pack.components.Count==5&&pack.plugins.Count==1&&pack.plugins[0].kind=="choice","composition includes only the custom plugins needed by its selected widgets");
        string file=Path.Combine(root,"share.qidesk-pack.json");File.WriteAllText(file,Store.Json.Serialize(pack));var incoming=ComponentPackages.Read(file);check(incoming.components.Any(p=>p.pluginId=="meal"&&p.text.Contains("饺子")),"UTF-8 component pack round-trip preserves custom random choices");
        var other=new Store(Path.Combine(root,"component-install"));other.Data.Groups.Clear();ComponentPackages.Install(other.Data,incoming);ComponentPackages.Install(other.Data,incoming);check(other.Data.ComponentPacks.Count==1&&other.Data.Plugins.Count==1,"installing the same component pack twice is idempotent");
        other.Checkpoint();var added=ComponentPackages.Add(other.Data,incoming,new[]{new Rect(0,0,1920,1080)},new Rect(40,60,650,700));other.Save();check(added.Count==5&&other.Data.Widgets.Select(w=>w.Id).Distinct().Count()==5&&added[0].X==40&&added[0].Y==60,"selected component combination starts at the left-button selected region with new instance IDs");
        var reload=new Store(other.Root);check(reload.Data.ComponentPacks.Count==1&&reload.Data.Widgets.Count==5,"installed combinations and widget layouts survive restart");check(other.Undo()&&other.Data.Widgets.Count==0&&other.Data.ComponentPacks.Count==1,"adding a component combination supports undo without uninstalling its pack");
        var placement=new State();placement.Groups.Clear();var single=ComponentPackages.FromPlugins(placement,new[]{"clock"},"时钟");ComponentPackages.Add(placement,single,new[]{new Rect(0,0,1920,1080)},null);ComponentPackages.Add(placement,single,new[]{new Rect(0,0,1920,1080)},null);check(!new Rect(placement.Widgets[0].X,placement.Widgets[0].Y,placement.Widgets[0].Width,placement.Widgets[0].Height).IntersectsWith(new Rect(placement.Widgets[1].X,placement.Widgets[1].Y,placement.Widgets[1].Width,placement.Widgets[1].Height)),"repeated left-click widget additions find free space instead of overlapping previous widgets");
        var state=new State();state.Groups.Clear();var tasks=WidgetPlugins.Create(state,"qidesk.tasks",new[]{new Rect(0,0,1920,1080)});tasks.CheckedTasks.Add(0);var focus=WidgetPlugins.Create(state,"qidesk.focus",new[]{new Rect(0,0,1920,1080)});focus.FocusUntil=DateTimeOffset.UtcNow.AddMinutes(5).ToString("o");state.CurrentWorkspace="D:\\private-project";var exported=ComponentPackages.Export(state,state.Widgets,"我的组合");string json=Store.Json.Serialize(exported);check(!json.Contains("private-project")&&!json.Contains("FocusUntil")&&!json.Contains("CheckedTasks")&&!json.Contains("Items"),"shared packs omit project paths file memberships task completion and running timer state");
        var moment=new DateTimeOffset(2026,10,13,12,0,0,TimeSpan.Zero);focus.FocusUntil=moment.AddSeconds(123).ToString("o");check(WidgetPlugins.FocusRemaining(focus,moment)==123&&WidgetPlugins.FocusRemaining(focus,moment.AddSeconds(124))==0,"focus countdown uses elapsed time rather than timer tick counts");focus.FocusUntil="";focus.FocusPausedSeconds=77;check(WidgetPlugins.FocusRemaining(focus,moment.AddHours(1))==77,"paused focus duration remains stable while time passes");
        string before=Store.Json.Serialize(other.Data);var collision=Store.Json.Deserialize<ComponentPack>(Store.Json.Serialize(incoming));collision.id="another-pack";collision.plugins[0].text="不同的选项";bool failed=false;try{ComponentPackages.Install(other.Data,collision);}catch{failed=true;}check(failed&&Store.Json.Serialize(other.Data)==before,"conflicting plugin installation leaves the complete previous library intact");
        File.WriteAllText(file,Store.Json.Serialize(incoming).Replace("\"format\":", "\"command\":\"run.exe\",\"format\":"));failed=false;try{ComponentPackages.Read(file);}catch{failed=true;}check(failed,"component package installer rejects unknown executable-command fields");
        var full=new State(){Pages=20,Page=19};full.Groups.Clear();ComponentPackages.Install(full,incoming);before=Store.Json.Serialize(full);failed=false;try{ComponentPackages.Add(full,incoming,new[]{new Rect(0,0,400,400)},new Rect(30,350,220,100));}catch{failed=true;}check(failed&&Store.Json.Serialize(full)==before,"combination placement at the page limit fails without partially adding widgets");
        var tutorialStore=new Store(Path.Combine(root,"tutorial-tests"));tutorialStore.Data.TutorialVersion=1;tutorialStore.Save();check(new Store(tutorialStore.Root).Data.TutorialVersion==1,"first-use tutorial completion persists across launches");
        string examples=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","code","plugins","examples"));if(!Directory.Exists(examples))examples=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","plugins","examples"));check(WidgetPlugins.Read(Path.Combine(examples,"what-to-eat.qidesk-plugin.json")).Kind=="choice"&&WidgetPlugins.Read(Path.Combine(examples,"creative-prompt.qidesk-plugin.json")).Kind=="choice"&&ComponentPackages.Read(Path.Combine(examples,"focus-desktop.qidesk-pack.json")).components.Count==4,"distributed meal inspiration and focus-desktop examples can be installed with the real package readers");check(WidgetPlugins.Read(Path.Combine(examples,"daily-water.qidesk-plugin.json")).Kind=="habit"&&ComponentPackages.Read(Path.Combine(examples,"utility-desk.qidesk-pack.json")).components.Count==4,"new renderer examples install with the real package readers");
    }
    public static void Native(string root,Action<bool,string> check){
        var store=new Store(Path.Combine(root,"component-native"));var c=new Controller(store);var manager=new ManagerWindow(c){Left=-20000,Top=-20000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};manager.Show();var windows=new List<WidgetWindow>();
        try{
            foreach(string id in new[]{"qidesk.tasks","qidesk.focus","qidesk.choice"}){var widget=WidgetPlugins.Create(store.Data,id,new[]{new Rect(0,0,1920,1080)});var w=new WidgetWindow(c,widget){Left=-20000,Top=-20000};windows.Add(w);c.Widgets.Add(w);w.Show();w.UpdateLayout();}
            var taskWindow=windows[0];var checkbox=Walk(taskWindow).OfType<CheckBox>().First();checkbox.IsChecked=true;checkbox.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));check(new Store(store.Root).Data.Widgets.First(w=>w.PluginId=="qidesk.tasks").CheckedTasks.Contains(0),"left-click task completion is saved by a real component window");
            check(taskWindow.Widget.TaskTimes.ContainsKey("0")&&!String.IsNullOrEmpty(taskWindow.Widget.TaskTimes["0"]),"completing a task records a completion time");check(Walk(taskWindow).OfType<TextBlock>().Any(t=>t.Text.Contains("已完成")&&t.Text.Contains("条")),"completed tasks collapse under a done section");check(Walk(taskWindow).OfType<TextBlock>().Where(t=>t.Text=="✕").All(t=>t.Visibility!=Visibility.Visible),"delete icons stay hidden until the row is hovered");
            check(Walk(taskWindow).OfType<TextBox>().Any(),"task widget exposes inline editable fields and an add box instead of a settings dialog");
            var addBox=Walk(taskWindow).OfType<TextBox>().Last();addBox.Text="面板直接添加";Walk(taskWindow).OfType<Button>().First(b=>Convert.ToString(b.Content)=="＋").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(WidgetPlugins.Lines(taskWindow.Widget.Text).Contains("面板直接添加")&&new Store(store.Root).Data.Widgets.First(w=>w.PluginId=="qidesk.tasks").Text.Contains("面板直接添加"),"adding a task directly from the panel persists without opening a dialog");
            var focus=windows[1];Walk(focus).OfType<Button>().First(b=>Convert.ToString(b.Content)=="开始").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(focus.Widget.FocusUntil.Length>0,"focus widget start button creates a persistent countdown");Walk(focus).OfType<Button>().First(b=>Convert.ToString(b.Content)=="暂停").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(focus.Widget.FocusUntil.Length==0&&focus.Widget.FocusPausedSeconds>0,"focus widget pause retains remaining duration");
            var choice=windows[2];Walk(choice).OfType<Button>().First(b=>Convert.ToString(b.Content)=="随机选一个").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(Walk(choice).OfType<TextBlock>().Any(t=>WidgetPlugins.Lines(choice.Widget.Text).Contains(t.Text)),"random-choice component draws an actual configured option after left click");
            var calcWidget=WidgetPlugins.Create(store.Data,"qidesk.calc",new[]{new Rect(0,0,1920,1080)});var calcWindow=new WidgetWindow(c,calcWidget){Left=-20000,Top=-20000};windows.Add(calcWindow);calcWindow.Show();calcWindow.UpdateLayout();
            foreach(string key in new[]{"1","+","2","="})Walk(calcWindow).OfType<Button>().First(b=>Convert.ToString(b.Content)==key).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            check(Walk(calcWindow).OfType<TextBlock>().Any(t=>t.Text=="3"),"calculator component computes entered arithmetic after real button clicks");
            var habitWidget=WidgetPlugins.Create(store.Data,"qidesk.habit",new[]{new Rect(0,0,1920,1080)});var habitWindow=new WidgetWindow(c,habitWidget){Left=-20000,Top=-20000};windows.Add(habitWindow);habitWindow.Show();habitWindow.UpdateLayout();
            Walk(habitWindow).OfType<Button>().First(b=>Convert.ToString(b.Content)=="今天打卡").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            check(new Store(store.Root).Data.Widgets.First(w=>w.PluginId=="qidesk.habit").Checkins.Contains(DateTime.Today.ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture)),"habit check-in button records today's date through a real component window");
            var preview=new SelectionPreview();bool selected=false;try{preview.Show();preview.ShowChoice(new Rect(-20000,-20000,300,200),delegate{},delegate{},delegate{selected=true;});check(preview.Choice.Items.Count==4,"left-button region menu offers group folder portal component and cancel choices");((MenuItem)preview.Choice.Items[2]).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));check(selected,"component option dispatches independently from group and folder creation");}finally{preview.Close();}
            // 「组件区」面板已移除
            var tutorial=new TutorialWindow(c){ShowActivated=false,Left=-20000,Top=-20000,WindowStartupLocation=WindowStartupLocation.Manual};try{tutorial.Show();tutorial.UpdateLayout();Walk(tutorial).OfType<Button>().First(b=>Convert.ToString(b.Content)=="下一步").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(Walk(tutorial).OfType<TextBlock>().Any(t=>t.Text.Contains("0.35")),"first-use tutorial advances to a concrete long-press rectangle selection lesson");}finally{tutorial.Close();}check(new Store(store.Root).Data.TutorialVersion==1,"closing the tutorial records completion without forcing component installation");
        }finally{foreach(var w in windows)w.Close();c.Widgets.Clear();manager.Quit();}
    }
    static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var item in Walk(VisualTreeHelper.GetChild(root,i)))yield return item;}
    static void Capture(Window w,string file){w.UpdateLayout();var bitmap=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(w);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(file))png.Save(stream);}
    public static int Render(){var app=new Application(){ShutdownMode=ShutdownMode.OnExplicitShutdown};string output=AppDomain.CurrentDomain.BaseDirectory;var store=new Store(Path.Combine(output,"component-render-state"));store.Data=new State();var c=new Controller(store);var manager=new ManagerWindow(c){Height=1080,Left=-20000,Top=-20000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};app.MainWindow=manager;
        try{manager.Show();manager.ShowSettingsPage("插件与组件");Capture(manager,Path.Combine(output,"component-library-preview.png"));var tutorial=new TutorialWindow(c){Left=-20000,Top=-20000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};tutorial.Show();Capture(tutorial,Path.Combine(output,"component-tutorial-preview.png"));tutorial.Close();foreach(string id in new[]{"clock","calendar","qidesk.weather","qidesk.tasks","qidesk.focus","qidesk.choice","qidesk.calc","qidesk.habit","qidesk.system","qidesk.photos","qidesk.music"}){var widget=WidgetPlugins.Create(store.Data,id,new[]{new Rect(0,0,1920,1080)});var window=new WidgetWindow(c,widget){Left=-20000,Top=-20000};try{window.Show();Capture(window,Path.Combine(output,"component-"+id+"-preview.png"));}finally{window.Close();}}return 0;}
        finally{manager.Quit();app.Shutdown();}
    }
}
}
